// Move, capture, check and game-end sounds (original, generated by scripts/gen-sfx.js).
import { createAudioPlayer, setAudioModeAsync } from 'expo-audio';

const FILES = {
  move: require('../assets/sfx/move.wav'),
  capture: require('../assets/sfx/capture.wav'),
  check: require('../assets/sfx/check.wav'),
  promote: require('../assets/sfx/promote.wav'),
  win: require('../assets/sfx/win.wav'),
  lose: require('../assets/sfx/lose.wav'),
  draw: require('../assets/sfx/draw.wav'),
};
const players = {};
let enabled = true;

export function setSoundEnabled(on) { enabled = !!on; }
export function initSound() {
  try { setAudioModeAsync({ playsInSilentMode: false, interruptionMode: 'mixWithOthers' }).catch(() => {}); } catch (e) {}
  Object.keys(FILES).forEach(k => { try { players[k] = createAudioPlayer(FILES[k]); } catch (e) {} });
}
export function play(name) {
  if (!enabled) return;
  const p = players[name]; if (!p) return;
  try { p.seekTo(0); p.play(); } catch (e) {}
}
// Picks the right sound for a finished move.
export function moveSound({ capture, check, promo }) { play(check ? 'check' : promo ? 'promote' : capture ? 'capture' : 'move'); }
